import sys

def main():
    a=list(map(int,sys.stdin.buffer.read().split()))
    if not a:return
    n=a[0]; pts=[(a[1+2*i],a[2+2*i]) for i in range(n)]
    # reorder by x
    order=sorted(range(n),key=lambda i:pts[i][0])
    y=[pts[i][1] for i in order]
    inc=[[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            inc[i][j]= not ((i<j and y[i]<y[j]) or (i>j and y[i]>y[j]))
    ans={0}
    # enumerate decreasing subsequences (antichains), retaining their resulting set
    def dfs(start, last, pm, sm):
        ans.add(sm)
        for j in range(start,n):
            if last<0 or inc[last][j]:
                # j must be incomparable with every selected point
                ok=True
                for k in range(n):
                    if (pm>>k)&1 and not inc[k][j]: ok=False; break
                if ok:
                    ns=0
                    for k in range(n):
                        if (pm>>k)&1 or all(inc[t][k] for t in range(n) if (pm>>t)&1 or t==j): ns|=1<<k
                    dfs(j+1,j,pm|(1<<j),ns)
    # closure for empty is all
    dfs(0,-1,0,(1<<n)-1)
    print(len(ans)%998244353)
main()

