    d = list(map(int, sys.stdin.buffer.read().split()))
    if not d:
        return
    n, X = d[0], d[1]
    machines = []
    z = 2
    for _ in range(n):
        machines.append(tuple(d[z:z+4]))
        z += 4

    def required(w, A, P, B, Q):
        m = w // A
        c = (w + A - 1) // A
        best = c * P
        for r in range(min(B, m + 1)):
            for x in (r, m - ((m - r) % B)):
                if x >= 0:
                    y = max(0, (w - A * x + B - 1) // B)
                    best = min(best, x * P + y * Q)
            x = c + ((r - c) % B)
            if x <= c:
                best = min(best, x * P)
        return best

    def feasible(w):
        total = 0
        for A, P, B, Q in machines:
            total += required(w, A, P, B, Q)
            if total > X:
                return False
        return True

    low = 0
    high = min(max(A, B) * X // min(P, Q) + 1
               for A, P, B, Q in machines)
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

