class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        C = [[0] * (m + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        good = [False] * (m + 1)
        for x in range(1, m + 1):
            y = x
            steps = 0
            while y != 1:
                y = y.bit_count()
                steps += 1
            good[x] = steps <= k - 1

        ans = 0
        ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = m - i - 1
                for total in range(1, m + 1):
                    need = total - ones
                    if good[total] and 0 <= need <= remaining:
                        ans = (ans + C[remaining][need]) % MOD
                ones += 1
        return ans

