        else: l,r,d=t,s,-1
        a.append((l,r,d))
    bad=[0]*m
    for j in range(m):
        l,r,d=a[j]
        for i in range(j):
            x,y,e=a[i]
            z=False
            if x==l or y==r:
                if (x==l and y!=r) or (y==r and x!=l): z=True
            # shared opposite endpoint
            if y==l or x==r:
                if (y==l and x!=l) or (x==r and y!=r): z=True
            # strict crossing
            if x<l<y<r and e==d: z=True
            if l<x<r<y and e==d: z=True
            if z:
                if bad[j]==0 or i+1<bad[j]: bad[j]=i+1
    seg=[0]*(4*m)
    def upd(p,v,x,lo,hi):
        if hi-lo==1: seg[x]=v; return
        md=(lo+hi)//2
        if p<md: upd(p,v,x*2,lo,md)
        else: upd(p,v,x*2+1,md,hi)
        seg[x]=max(seg[x*2],seg[x*2+1])
    def qry(L,R,x,lo,hi):
        if R<=lo or hi<=L:return 0
        if L<=lo and hi<=R:return seg[x]
