        return max(qry(L,R,x*2,lo,md),qry(L,R,x*2+1,md,hi))
    for i,v in enumerate(bad): upd(i,v,1,0,m)
    out=[]
    for _ in range(q):
        l=next(it)-1; r=next(it)
        out.append('Yes' if qry(l+1,r,1,0,m)<l+1 else 'No')
    print('\n'.join(out))
