import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    u = data[2::2]
    d = data[3::2]
    hi = min(U + D for U, D in zip(u, d))
    lo = 0
    def feasible(h):
        low = max(0, h - d[0])
        high = min(u[0], h)
        if low > high:
            return False
        for U, D in zip(u[1:], d[1:]):
            nl = max(0, h - D, low - x)
            nh = min(U, h, high + x)
            if nl > nh:
                return False
            low, high = nl, nh
        return True
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    print(sum(u) + sum(d) - n * lo)

solve()

