import random, heapq

def fast(H,W,X,P,Q,a):
 cur=a[P][Q]; seen={(P,Q)}; h=[]
 for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
  i,j=P+di,Q+dj
  if 0<=i<H and 0<=j<W: seen.add((i,j));heapq.heappush(h,(a[i][j],i,j))
 while h and h[0][0]*X<cur:
  v,i,j=heapq.heappop(h);cur+=v
  for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
   x,y=i+di,j+dj
   if 0<=x<H and 0<=y<W and (x,y) not in seen:seen.add((x,y));heapq.heappush(h,(a[x][y],x,y))
 return cur

def brute(H,W,X,P,Q,a):
 best=a[P][Q]; states={(P,Q, frozenset([(P,Q)]),a[P][Q])}
 # represent absorbed set and pos; initial pos, remaining. enumerate paths
 todo=[(P,Q,frozenset([(P,Q)]),a[P][Q])]
 while todo:
  i,j,used,s=todo.pop();best=max(best,s)
  for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
   x,y=i+di,j+dj
   if 0<=x<H and 0<=y<W and (x,y) not in used and a[x][y]*X<s:
    z=used|{(x,y)}; todo.append((x,y,z,s+a[x][y]))
 return best
