class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)
        avail = list(range(1, n + 1))
        ans = []
        prev = None

        def count(o, e, req, length):
            if length == 0:
                return 1
            if req == 1:
                need_o, need_e = (length + 1) // 2, length // 2
            else:
                need_o, need_e = length // 2, (length + 1) // 2
            if o != need_o or e != need_e:
                return 0
            return min(CAP, fact[o] * fact[e])

        for pos in range(n):
            chosen = None
            for x in avail:
                parity = x & 1
                if prev is not None and parity == prev:
                    continue
                odd = sum(y & 1 for y in avail if y != x)
                even = n - pos - 1 - odd
                ways = count(odd, even, 1 - parity, n - pos - 1)
                if k > ways:
                    k -= ways
                elif ways:
                    chosen = x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            avail.remove(chosen)
            prev = chosen & 1
        return ans

