    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i-1] * 10 % k
        weights = []
        for i in range(m):
            j = n - 1 - i
            weights.append(powers[i] if i == j else (powers[i] + powers[j]) % k)
        dp = [bytearray(k) for _ in range(m + 1)]
        dp[m][0] = 1
        for i in range(m - 1, -1, -1):
            w = weights[i]
            for r in range(k):
                if dp[i+1][r]:
                    for d in range(10):
                        dp[i][(r + d*w) % k] = 1
        rem = 0
        left = []
        for i, w in enumerate(weights):
            for d in range(9, (1 if i == 0 else 0) - 1, -1):
                nr = (rem + d*w) % k
                if dp[i+1][(-nr) % k]:
                    left.append(str(d))
                    rem = nr
                    break
        s = ''.join(left)
        return s + (s[:-1][::-1] if n % 2 else s[::-1])

