from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        stack = []
        nxt = [n] * n
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        up = [nxt + [n]]
        weight = [0] * (n + 1)
        for i in range(n):
            weight[i] = nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
        weights = [weight]
        for _ in range(1, levels):
            previous_up = up[-1]
            previous_weight = weights[-1]
            current_up = [0] * (n + 1)
            current_weight = [0] * (n + 1)
            for i in range(n + 1):
                middle = previous_up[i]
                current_up[i] = previous_up[middle]
                current_weight[i] = previous_weight[i] + previous_weight[middle]
            up.append(current_up)
            weights.append(current_weight)

        def cost(left, right):
            current = left
            result = 0
            for b in range(levels - 1, -1, -1):
                if up[b][current] <= right:
                    result += weights[b][current]
                    current = up[b][current]
            return result + nums[current] * (right - current + 1) - (pref[right + 1] - pref[current])

        left = 0
        answer = 0
        for right in range(n):
            while cost(left, right) > k:
                left += 1
            answer += right - left + 1
        return answer

