import sys
from functools import lru_cache

def main():
    d = list(map(int, sys.stdin.buffer.read().split()))
    if not d:
        return
    n, m, l = d[:3]
    v = d[3:]
    k = n + m + l
    pw = [1]
    for _ in range(k):
        pw.append(pw[-1] * 3)
    initial = sum(pw[i] for i in range(n, n + m)) + 2 * sum(pw[i] for i in range(n + m, k))
    sys.setrecursionlimit(2000000)

    @lru_cache(None)
    def winning(state, turn):
        loc = [(state // pw[i]) % 3 for i in range(k)]
        for i in range(k):
            if loc[i] != turn:
                continue
            placed = state + (2 - turn) * pw[i]
            if not winning(placed, 1 - turn):
                return True
            for j in range(k):
                if loc[j] == 2 and v[j] < v[i]:
                    next_state = placed - (2 - turn) * pw[j]
                    if not winning(next_state, 1 - turn):
                        return True
        return False

    print("Takahashi" if winning(initial, 0) else "Aoki")

if __name__ == '__main__':
    main()

